const raw = $json.snapshot;
const snapshot = typeof raw === 'string' ? JSON.parse(raw) : raw;
const generatedAt = new Date(snapshot?.generated_at ?? Date.now());
const safeTime = Number.isNaN(generatedAt.getTime()) ? new Date() : generatedAt;
const bucketMs = Math.floor(safeTime.getTime() / 300000) * 300000;
const bucket = new Date(bucketMs)
  .toISOString()
  .slice(0, 16)
  .replace(/[-:T]/g, '');

return {
  event_id: 'OBS-' + bucket,
  snapshot
};
